public class GProbe {static void check(boolean b,String n){if(!b)throw new AssertionError(n);System.out.println(n+"=PASS");} public static void main(String[]a)throws Exception{for(int i=0;i<3;i++){String v=i==2?a[1]:a[0];var o=new DockerSandboxClientOptions().image("alpine:3").workspaceRoot("/workspace").network("none").additionalRunArgs("--cap-drop=ALL","--security-opt=no-new-privileges","--mount","type=volume,source="+v+",target=/workspace");var s=new DockerSandboxClient().create(new WorkspaceSpec(),new NoopSnapshotSpec(),o);try{s.start();var f=ProjectAgentFoundationTools.filesystemTool(s);var wm=new WorkspaceManager(Path.of(a[2],"workspace"+i),new PinnedSandboxFilesystem(s));if(i==0){check(!f.writeFile(null,"/workspace/runs/one/probe.txt","G-synthetic-owned").startsWith("Error"),"FILE_WRITE");check(new MemorySaveTool(wm).memorySave(null,"G-synthetic-memory").startsWith("Saved"),"NATIVE_MEMORY_SAVE");check(ProjectAgentFoundationTools.shellTool(s).execute(null,"printf G-safe-shell",null,5).contains("G-safe-shell"),"SHELL_EXECUTE");check(ProjectAgentFoundationTools.shellTool(s).execute(null,"printf no","../outside",5).startsWith("Error"),"WORKDIR_TRAVERSAL_DENIED");check(ProjectAgentFoundationTools.shellTool(s).execute(null,"test ! -e /Users/mac/Documents/ruoyi-ai && printf isolated",null,5).contains("isolated"),"HOST_REPO_ABSENT");System.out.println("FILE_OUTSIDE_ROOT_DENIED="+f.readFile(null,"/etc/passwd",0,0).startsWith("Error"));}if(i==1){check(f.readFile(null,"/workspace/runs/one/probe.txt",0,0).contains("G-synthetic-owned"),"FILE_COLD_PERSIST");check(new MemoryGetTool(wm).memoryGet(null,"MEMORY.md",1,100).contains("G-synthetic-memory"),"NATIVE_MEMORY_COLD_PERSIST");check(new MemorySearchTool(wm).memorySearch(null,"G-synthetic-memory").contains("G-synthetic-memory"),"NATIVE_MEMORY_SEARCH");System.out.println("SIBLING_RUN_READ_ALLOWED="+f.readFile(null,"/workspace/runs/one/probe.txt",0,0).contains("G-synthetic-owned"));}if(i==2){check(f.readFile(null,"/workspace/runs/one/probe.txt",0,0).startsWith("Error"),"OTHER_VOLUME_FILE_ABSENT");check(!new MemoryGetTool(wm).memoryGet(null,"MEMORY.md",1,100).contains("G-synthetic-memory"),"OTHER_VOLUME_MEMORY_ABSENT");}}finally{s.shutdown();System.out.println("OWN_CONTAINER_SHUTDOWN="+i);}}}}
